-- Reframe the curriculum around observable diagnostic evidence. Historical
-- attempts remain unchanged because they use immutable question snapshots.

ALTER TABLE questions
  ADD COLUMN diagnostic_role TEXT NOT NULL DEFAULT 'ANCHOR',
  ADD COLUMN construct_code TEXT NOT NULL DEFAULT 'FOUNDATION',
  ADD COLUMN content_version INTEGER NOT NULL DEFAULT 1,
  ADD CONSTRAINT questions_diagnostic_role_allowed CHECK (
    diagnostic_role IN ('ANCHOR', 'VERIFICATION', 'CHALLENGE')
  ),
  ADD CONSTRAINT questions_content_version_positive CHECK (content_version > 0);

CREATE TABLE skill_diagnostic_blueprints (
  skill_id UUID PRIMARY KEY REFERENCES skills(id) ON DELETE CASCADE,
  anchor_objective TEXT NOT NULL,
  application_objective TEXT NOT NULL,
  boundary_objective TEXT NOT NULL,
  minimum_direct_observations SMALLINT NOT NULL DEFAULT 3,
  minimum_cognitive_levels SMALLINT NOT NULL DEFAULT 2,
  minimum_difficulty_bands SMALLINT NOT NULL DEFAULT 2,
  requires_application_evidence BOOLEAN NOT NULL DEFAULT TRUE,
  blueprint_version INTEGER NOT NULL DEFAULT 2,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT skill_diagnostic_blueprint_minima CHECK (
    minimum_direct_observations >= 2
    AND minimum_cognitive_levels >= 2
    AND minimum_difficulty_bands >= 2
    AND blueprint_version > 0
  )
);

INSERT INTO skill_diagnostic_blueprints (
  skill_id, anchor_objective, application_objective, boundary_objective
)
SELECT id,
       'Distinguish the essential meaning and invariant of ' || name || ' from plausible misconceptions.',
       'Apply ' || name || ' correctly in a representative course scenario.',
       'Identify when ' || name || ' is valid, insufficient, or inappropriate under changed constraints.'
FROM skills
WHERE is_active;

-- Retire the synthetic application templates. They remain in the database for
-- auditability and historical foreign keys but cannot be selected again.
UPDATE questions
SET status = 'RETIRED', updated_at = NOW()
WHERE slug LIKE 'adaptive-%-application-v2';

UPDATE questions
SET diagnostic_role = CASE
      WHEN question_type = 'MULTI_SELECT' OR cognitive_level = 'ANALYZE' THEN 'CHALLENGE'
      WHEN question_type = 'NUMERIC' OR cognitive_level = 'APPLY' THEN 'VERIFICATION'
      ELSE 'ANCHOR'
    END,
    construct_code = CASE
      WHEN question_type = 'MULTI_SELECT' OR cognitive_level = 'ANALYZE' THEN 'BOUNDARY'
      WHEN question_type = 'NUMERIC' OR cognitive_level = 'APPLY' THEN 'APPLICATION'
      ELSE 'FOUNDATION'
    END,
    content_version = 2
WHERE status = 'ACTIVE' AND question_purpose = 'DIAGNOSTIC';

