    {"slug":"programming-variables-boundary-v2","skill":"programming-variables","type":"MULTI_SELECT","level":"ANALYZE","difficulty":3,"prompt":"Select every statement that correctly distinguishes assignment from equality testing.","explanation":"Assignment stores a value in a variable; equality testing produces a Boolean comparison result. Assignment does not prove permanent equality.","options":[{"c":"Assignment can change stored program state","ok":true},{"c":"Equality testing produces a true-or-false result","ok":true},{"c":"After x is assigned y, x and y must remain equal forever","ok":false,"code":"VARIABLE_ASSIGNMENT_PERMANENT_EQUALITY"},{"c":"Equality testing always modifies both operands","ok":false,"code":"COMPARISON_MUTATES_VALUES"}]},

    {"slug":"queues-application-v2","skill":"queues","type":"SINGLE_CHOICE","level":"APPLY","difficulty":2,"prompt":"A queue receives A, then B, then C. One item is removed, then D is added. What is the removal order of the remaining items?","explanation":"A is removed first; the remaining FIFO order is B, C, D.","options":[{"c":"B, C, D","ok":true},{"c":"D, C, B","ok":false,"code":"QUEUE_AS_STACK"},{"c":"A, B, C","ok":false,"code":"QUEUE_REMOVAL_IGNORED"},{"c":"C, B, D","ok":false,"code":"QUEUE_REVERSES_EXISTING_ITEMS"}]},
    {"slug":"queues-boundary-v2","skill":"queues","type":"MULTI_SELECT","level":"ANALYZE","difficulty":3,"prompt":"Select every situation naturally modeled by a FIFO queue.","explanation":"Arrival-order service and BFS frontiers use FIFO. Undo history uses a stack and priority scheduling needs priority ordering.","options":[{"c":"Serving requests in arrival order","ok":true},{"c":"Processing the next BFS frontier","ok":true},{"c":"Undoing the most recent editor action first","ok":false,"code":"QUEUE_AS_STACK"},{"c":"Always processing the highest-priority job first","ok":false,"code":"QUEUE_AS_PRIORITY_QUEUE"}]},

