    {"slug":"topological-sorting-application-v2","skill":"topological-sorting","type":"SINGLE_CHOICE","level":"APPLY","difficulty":4,"prompt":"Kahn's algorithm processes fewer vertices than the directed graph contains. What does this establish?","explanation":"A remaining directed cycle prevents every remaining vertex from reaching indegree zero, so no topological ordering exists.","options":[{"c":"The graph contains a directed cycle","ok":true},{"c":"The graph is disconnected and therefore invalid","ok":false,"code":"TOPOLOGICAL_DISCONNECTED_INVALID"},{"c":"The queue implementation was necessarily FIFO-wrong","ok":false,"code":"TOPOLOGICAL_BLAMES_QUEUE"},{"c":"The graph has multiple valid topological orders","ok":false,"code":"TOPOLOGICAL_PARTIAL_AS_MULTIPLE"}]},
    {"slug":"topological-sorting-boundary-v2","skill":"topological-sorting","type":"MULTI_SELECT","level":"ANALYZE","difficulty":5,"prompt":"Select every true statement about topological ordering.","explanation":"It exists only for DAGs, respects every directed dependency, and can be non-unique. It is not a shortest-path ordering.","options":[{"c":"Every directed edge u to v places u before v","ok":true},{"c":"A DAG may have more than one valid order","ok":true},{"c":"Every directed graph has such an order","ok":false,"code":"TOPOLOGICAL_ALLOWS_CYCLES"},{"c":"The order always lists vertices by distance from one source","ok":false,"code":"TOPOLOGICAL_AS_BFS_DISTANCE"}]},

    {"slug":"tree-traversal-application-v2","skill":"tree-traversal","type":"SINGLE_CHOICE","level":"APPLY","difficulty":4,"prompt":"To evaluate an expression tree where operators are internal nodes, which traversal naturally evaluates children before their operator?","explanation":"Postorder processes left and right subexpressions before applying the operator at their parent.","options":[{"c":"Postorder","ok":true},{"c":"Preorder","ok":false,"code":"EXPRESSION_EVAL_AS_PREFIX_PROCESS"},{"c":"Level order","ok":false,"code":"EXPRESSION_EVAL_BY_DEPTH"},{"c":"Inorder without parentheses","ok":false,"code":"EXPRESSION_INORDER_UNAMBIGUOUS"}]},
    {"slug":"tree-traversal-boundary-v2","skill":"tree-traversal","type":"MULTI_SELECT","level":"ANALYZE","difficulty":5,"prompt":"Select every correct traversal use.","explanation":"Preorder can serialize structure with null markers, and level order groups nodes by depth. Inorder is sorted only for BSTs; postorder does not inherently find shortest graph paths.","options":[{"c":"Preorder with null markers can serialize a binary tree","ok":true},{"c":"Level order can process nodes by depth","ok":true},{"c":"Inorder sorts every arbitrary binary tree","ok":false,"code":"INORDER_ALWAYS_SORTED"},{"c":"Postorder guarantees shortest paths in a weighted graph","ok":false,"code":"TREE_TRAVERSAL_AS_SHORTEST_PATH"}]},

    {"slug":"tries-application-v2","skill":"tries","type":"SINGLE_CHOICE","level":"APPLY","difficulty":4,"prompt":"A trie contains the word car, and the path c-a continues to t. What distinguishes car from the prefix ca?","explanation":"A terminal marker on the node for r records that car is a complete stored key; path existence alone represents a prefix.","options":[{"c":"A terminal marker at the r node","ok":true},{"c":"The r node must have no children","ok":false,"code":"TRIE_WORD_MUST_BE_LEAF"},{"c":"The characters are sorted alphabetically","ok":false,"code":"TRIE_WORD_AS_SORTED_CHARS"},{"c":"The path length is greater than two","ok":false,"code":"TRIE_LENGTH_DEFINES_WORD"}]},
    {"slug":"tries-boundary-v2","skill":"tries","type":"MULTI_SELECT","level":"ANALYZE","difficulty":5,"prompt":"Select every true statement about a character trie.","explanation":"Lookup depends mainly on key length and shared prefixes reuse nodes. Memory can be high, and ordinary tries do not rank suggestions by frequency unless augmented.","options":[{"c":"Lookup time is proportional to the key length","ok":true},{"c":"Keys with common prefixes share path nodes","ok":true},{"c":"Memory use is always lower than a hash table","ok":false,"code":"TRIE_ALWAYS_MEMORY_EFFICIENT"},{"c":"Autocomplete frequency ranking is automatic without stored counts","ok":false,"code":"TRIE_AUTOMATIC_RANKING"}]},

    {"slug":"two-pointers-application-v2","skill":"two-pointers","type":"SINGLE_CHOICE","level":"APPLY","difficulty":3,"prompt":"In a sorted ascending array, the sum at left and right is smaller than the target. Which pointer movement can increase the sum?","explanation":"Moving the left pointer right replaces the smaller value with an equal or larger value; moving right left would not increase the sum.","options":[{"c":"Move the left pointer right","ok":true},{"c":"Move the right pointer left","ok":false,"code":"TWO_POINTER_DIRECTION_REVERSED"},{"c":"Move both pointers outside the array","ok":false,"code":"TWO_POINTER_SKIP_SEARCH"},{"c":"Keep both pointers fixed","ok":false,"code":"TWO_POINTER_NO_PROGRESS"}]},
    {"slug":"two-pointers-boundary-v2","skill":"two-pointers","type":"MULTI_SELECT","level":"ANALYZE","difficulty":4,"prompt":"Select every condition supporting the opposite-end two-pointer sum technique.","explanation":"The sequence must be ordered under the comparison and pointer movement must eliminate impossible pairs. Arbitrary unsorted data does not support the same rule directly.","options":[{"c":"Values are sorted under the comparison used","ok":true},{"c":"Each pointer move safely discards impossible pairs","ok":true},{"c":"Values may be in arbitrary order with no preprocessing","ok":false,"code":"TWO_POINTER_IGNORES_ORDER"},{"c":"Both pointers must always move together","ok":false,"code":"TWO_POINTER_ALWAYS_MOVE_BOTH"}]}
  ]
  $bank$::jsonb) AS item(
    slug TEXT, skill TEXT, type TEXT, level TEXT, difficulty SMALLINT,
    prompt TEXT, explanation TEXT, options JSONB
  )
), inserted AS (
  INSERT INTO questions (
    id, skill_id, slug, prompt, question_type, difficulty, explanation,
    status, discrimination, guess_probability, cognitive_level,
    calibration_state, question_purpose, diagnostic_role, construct_code, content_version
  )
  SELECT gen_random_uuid(), skill.id, authored.slug, authored.prompt, authored.type,
         CASE WHEN authored.level = 'ANALYZE' THEN authored.difficulty
              ELSE LEAST(authored.difficulty, 3) END,
         authored.explanation, 'ACTIVE',
         CASE WHEN authored.level = 'ANALYZE' THEN 1.300 ELSE 1.200 END,
         CASE WHEN authored.type = 'MULTI_SELECT' THEN 0.125 ELSE 0.250 END,
         authored.level, 'EXPERT_PRIOR', 'DIAGNOSTIC',
         CASE WHEN authored.level = 'ANALYZE' THEN 'CHALLENGE' ELSE 'VERIFICATION' END,
         CASE WHEN authored.level = 'ANALYZE' THEN 'BOUNDARY' ELSE 'APPLICATION' END,
         2
  FROM authored
  JOIN skills skill ON skill.slug = authored.skill
  ON CONFLICT (slug) DO UPDATE SET
    prompt = EXCLUDED.prompt, question_type = EXCLUDED.question_type,
    difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation,
    status = 'ACTIVE', discrimination = EXCLUDED.discrimination,
    guess_probability = EXCLUDED.guess_probability,
    cognitive_level = EXCLUDED.cognitive_level,
    diagnostic_role = EXCLUDED.diagnostic_role,
    construct_code = EXCLUDED.construct_code,
    content_version = EXCLUDED.content_version,
    updated_at = NOW()
  RETURNING id, slug
)
INSERT INTO question_options (
  id, question_id, option_key, content, is_correct, misconception_code
)
SELECT gen_random_uuid(), inserted.id, chr((64 + option.ordinality)::integer)::char(1),
       option.value->>'c', (option.value->>'ok')::boolean,
       NULLIF(option.value->>'code', '')
FROM authored
JOIN inserted ON inserted.slug = authored.slug
CROSS JOIN LATERAL jsonb_array_elements(authored.options) WITH ORDINALITY AS option(value, ordinality)
ON CONFLICT (question_id, option_key) DO UPDATE SET
  content = EXCLUDED.content,
  is_correct = EXCLUDED.is_correct,
  misconception_code = EXCLUDED.misconception_code;

INSERT INTO question_skill_mappings (question_id, skill_id, mapping_type, evidence_weight)
SELECT id, skill_id, 'PRIMARY', 1.0000
FROM questions
WHERE content_version = 2
  AND diagnostic_role IN ('VERIFICATION', 'CHALLENGE')
ON CONFLICT (question_id, skill_id) DO UPDATE SET
  mapping_type = EXCLUDED.mapping_type,
  evidence_weight = EXCLUDED.evidence_weight;

WITH additions AS (
  SELECT assessment.id AS assessment_id, question.id AS question_id,
         ROW_NUMBER() OVER (
           PARTITION BY assessment.id ORDER BY course_skill.sequence, question.slug
         )::smallint AS offset_sequence
  FROM assessments assessment
  JOIN course_skills course_skill ON course_skill.course_id = assessment.course_id
  JOIN questions question ON question.skill_id = course_skill.skill_id
    AND question.status = 'ACTIVE'
    AND question.question_purpose = 'DIAGNOSTIC'
    AND question.content_version = 2
    AND question.diagnostic_role IN ('VERIFICATION', 'CHALLENGE')
  WHERE assessment.status = 'ACTIVE'
    AND assessment.assessment_type = 'DIAGNOSTIC'
    AND NOT EXISTS (
      SELECT 1 FROM assessment_questions existing
      WHERE existing.assessment_id = assessment.id
        AND existing.question_id = question.id
    )
), maxima AS (
  SELECT assessment.id AS assessment_id,
         COALESCE(MAX(existing.sequence), 0)::smallint AS maximum_sequence
  FROM assessments assessment
  LEFT JOIN assessment_questions existing ON existing.assessment_id = assessment.id
  GROUP BY assessment.id
)
INSERT INTO assessment_questions (assessment_id, question_id, sequence)
SELECT additions.assessment_id, additions.question_id,
       (maxima.maximum_sequence + additions.offset_sequence)::smallint
FROM additions
JOIN maxima ON maxima.assessment_id = additions.assessment_id
ON CONFLICT (assessment_id, question_id) DO NOTHING;

UPDATE system_metadata
SET value = value || '{"phase":25,"status":"curriculum_diagnostic_bank_v2","diagnosticContentVersion":2}'::jsonb,
    updated_at = NOW()
WHERE key = 'application';
